def git_release():
    """(tag, commit) if HEAD of the code repository is a tagged release, else None."""
    import subprocess
    try:
        commit = subprocess.run(["git", "-C", str(ROOT), "rev-parse", "HEAD"], capture_output=True, text=True, check=True).stdout.strip()
        tag = subprocess.run(["git", "-C", str(ROOT), "describe", "--tags", "--exact-match", "HEAD"], capture_output=True, text=True, check=True).stdout.strip()
        dirty = subprocess.run(["git", "-C", str(ROOT), "status", "--porcelain"], capture_output=True, text=True, check=True).stdout.strip()
        return (tag, commit) if tag and not dirty else None
    except Exception:
        return None


REPO_URL = "https://github.com/okanss/esaog"
DOI_MARK = "[AUTHOR ACTION REQUIRED: insert Zenodo DOI after creating final release]"
PUBLIC = False  # set True once the GitHub repository is public


def fill_release(s):
    rel = git_release()
    if not rel:
        return s
    tag, commit = rel
    s = s.replace("[AUTHOR ACTION REQUIRED: tag a release]", f"{tag} (software release; distinct from the architecture version)")
    s = s.replace("[AUTHOR ACTION REQUIRED: insert commit hash]", commit)
    s = s.replace("[AUTHOR ACTION REQUIRED: insert repository URL]", f"\\url{{{REPO_URL}}}" + ("" if PUBLIC else " (private until submission)"))
    s = s.replace("[AUTHOR ACTION REQUIRED: insert persistent repository URL, release tag, commit hash and archive DOI]",
                  f"\\url{{{REPO_URL}}} (software release {tag}, Git commit \\texttt{{{commit}}}" + ("" if PUBLIC else "; private until submission") + ")")
    s = s.replace("[AUTHOR ACTION REQUIRED: choose licence]", "the MIT licence (code) and CC BY 4.0 (benchmark, ontology, shapes, queries, prompts and results)")
    return s


